def brute_force(grid, capacity):
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                count += math.ceil(1 / capacity)
    return count

# Solution 2: Binary Search (Accepted)
def binary_search(grid, capacity):
    low, high = 0, sum([sum(row) for row in grid])
    while low < high:
        mid = (low + high) // 2
        if check(grid, capacity, mid):
            high = mid
        else:
            low = mid + 1
    return low

def check(grid, capacity, target):
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                count += math.ceil(1 / capacity)
    return count <= target

return binary_search(grid, capacity)

