def max_len_sub(arr,n):
  dp = [[0]*n for _ in range(n)]
  for i in range(n):
    dp[i][i] = 1
  for l in range(2,n+1):
    for i in range(n-l+1):
      j = i+l-1
      if arr[i]==arr[j]-l:
        dp[i][j] = dp[i+1][j-1]+1
      else:
        dp[i][j] = max(dp[i+1][j],dp[i][j-1])
  return dp[0][n-1]

